    private void disableSkuSpecificApps() {
        String[] apkList = this.mContext.getResources().getStringArray(R.array.config_companionPermSyncEnabledCerts);
        String[] skuArray = this.mContext.getResources().getStringArray(R.array.config_companionDevicePackages);
        if (ArrayUtils.isEmpty(apkList)) {
            return;
        }
        String sku = SystemProperties.get("ro.boot.hardware.sku");
        if (!TextUtils.isEmpty(sku) && ArrayUtils.contains(skuArray, sku)) {
            return;
        }
        for (String packageName : apkList) {
            setSystemAppHiddenUntilInstalled(packageName, true);
            for (UserInfo user : this.mInjector.getUserManagerInternal().getUsers(false)) {
                setSystemAppInstallState(packageName, false, user.id);
            }
        }
    }

